/**
 * Wills Farms letterhead artwork for the offer letter PDF
 * (src/lib/reports/OfferLetterDocument.tsx).
 *
 * Embedded as base64 data URIs directly in code (rather than read from a
 * public/ file path or fetched over the network) so PDF generation in
 * pages/api/careers/onboarding/offer-letter/pdf.ts has no filesystem or
 * network dependency at runtime, regardless of hosting environment.
 *
 * Source: the company's official offer-letter template (logo + full
 * address block, and the isolated pig logo mark cropped from the same
 * artwork for use as a page watermark).
 */

/** Full letterhead: logo + location/postal address + contact details.
 * Original artwork is 1205x342px. */
export const WILLS_FARMS_LETTERHEAD_DATA_URI =
  "data:image/png;base64,";

/** Isolated pig logo mark only (no text), cropped from the same artwork,
 * for use as a low-opacity background watermark. Original crop is
 * 411x275px. */
export const WILLS_FARMS_LOGO_MARK_DATA_URI =
  "data:image/png;base64,";
